//! Cargo-driven `inetmib1.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is inetmib1-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x73b70000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff0c000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff0c000000u64)),
        o => panic!("inetmib1-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:wine", "import:iphlpapi", "import:snmpapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "engine:oldnames"],
        "x86_64" => &["body", "engine:wine", "import:iphlpapi", "import:snmpapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "engine:oldnames"],
        "aarch64" => &["body", "engine:wine", "import:iphlpapi", "import:snmpapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("inetmib1-rust")
        .spec2def("dll/win32/inetmib1/inetmib1.spec", "inetmib1.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll", "iphlpapi")
        .import_lib("dll/win32/snmpapi/snmpapi.spec", "snmpapi.dll", "snmpapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
